function aquariumFishFrame(tank, i, time, out = {}) {
  const large = i === 0, scale2 = large ? tank.hero : 0.32 + i % 4 * 0.13;
  const extent2 = scale2 * 2.05;
  const rx = Math.max(0.2, tank.w / 2 - extent2 - 0.7), rz = Math.max(0.2, tank.d / 2 - extent2 - 0.7);
  const a = time * (large ? 0.16 : 0.22 + i % 3 * 0.035) + i * 2.399 + tank.index * 0.8;
  const x = Math.sin(a) * rx, z = Math.cos(a) * rz;
  const near = Math.max(0, (Math.cos(a) - 0.65) / 0.35);
  let yaw = Math.atan2(Math.cos(a) * rx, -Math.sin(a) * rz);
  yaw += Math.atan2(Math.sin(-yaw), Math.cos(-yaw)) * near * 0.7;
  const y = large ? tank.h * 0.44 + Math.sin(a * 1.35) * 0.25 : 1.6 + i % 4 * (tank.h - 3.1) / 4 + Math.sin(a * 1.4 + i) * 0.35;
  out.x = x;
  out.y = y;
  out.z = z;
  out.yaw = yaw;
  out.scale = scale2;
  out.tail = Math.sin(time * (large ? 2.7 : 4.2) + i) * 0.34;
  out.fin = Math.sin(time * 3.3 + i) * 0.3;
  out.color = palette[(i + tank.index) % palette.length];
  out.near = near;
  return out;
}

