  ["purple-vortex", "\u0424\u0456\u043E\u043B\u0435\u0442\u043E\u0432\u0430 \u0432\u043E\u0440\u043E\u043D\u043A\u0430", "\u{1F49C}", 78, 1, 3, 12163830, 16040331, 1.9, "\u0412\u0438\u0441\u043E\u043A\u0438\u0439 \u0440\u043E\u0437\u0433\u0456\u043D \u0443 \u0432\u0435\u043B\u0438\u0447\u0435\u0437\u043D\u0443 \u0444\u0456\u043E\u043B\u0435\u0442\u043E\u0432\u0443 \u0447\u0430\u0448\u0443, \u043E\u0431\u0435\u0440\u0442\u0430\u043D\u043D\u044F \u0439 \u043E\u043A\u0440\u0435\u043C\u0438\u0439 \u0432\u0438\u0445\u0456\u0434\u043D\u0438\u0439 \u043A\u0430\u043D\u0430\u043B."],
  ["mega-loops", "\u041C\u0435\u0433\u0430-\u043F\u0435\u0442\u043B\u0456", "\u{1F3A2}", 86, 1, 1, 8772346, 16030674, 2.8, "\u0422\u0440\u0438 \u0432\u0435\u043B\u0438\u043A\u0456 \u043A\u043E\u043B\u044C\u043E\u0440\u043E\u0432\u0456 \u043F\u0435\u0442\u043B\u0456, \u0448\u0432\u0438\u0434\u043A\u0456 \u043F\u043E\u0432\u043E\u0440\u043E\u0442\u0438 \u0439 \u043F\u0440\u043E\u0441\u0442\u043E\u0440\u0438\u0439 \u0444\u0456\u043D\u0456\u0448\u043D\u0438\u0439 \u0431\u0430\u0441\u0435\u0439\u043D."]
