var megaRide = (id) => MEGA_RIDES.find((r) => r.id === id);
function outsideMegaPlots(x, z, plots, biome, radius = 0.6, out = {}) {
  for (let pass = 0; pass < 3; pass++)
    for (const p of plots) {
      if (p.biome !== biome) continue;
      const hx = p.w / 2 + radius + 0.08, hz = p.d / 2 + radius + 0.08, dx = x - p.x, dz = z - p.z;
      if (Math.abs(dx) >= hx || Math.abs(dz) >= hz) continue;
      if (hx - Math.abs(dx) < hz - Math.abs(dz)) x = p.x + (dx < 0 ? -hx : hx);
      else z = p.z + (dz < 0 ? -hz : hz);
    }
  out.x = x;
  out.z = z;
  return out;
}

