function biomeReservations(id) {
  if (id === ZOO_BIOME.id) return [{ x: 0, z: 0, w: ZOO_RADIUS * 2, d: ZOO_RADIUS * 2 }];
  if (isRetiredBiome(id)) return [];
  const farm = magicFarmLayout(id);
  if (farm) {
    const [x, z, rx, rz] = farm.pond;
    return [...farm.plants.map((p) => ({ x: p.x, z: p.z, w: p.radius * 2 + 1.5, d: p.radius * 2 + 1.5 })), { x, z, w: rx * 2 + 4, d: rz * 2 + 4 }, { x: 0, z: 71, w: 78, d: 14 }];
  }
  if (id === JOB_CITY_ID) return jobReservations();
  if (id === "aquarium")
    return [
      { x: 0, z: 0, w: AQUARIUM_BUILDING.w + 1, d: AQUARIUM_BUILDING.d + 1 }
    ];
  if (id === "bikini") return bikiniReservations();
  if (id === "foodcourt") return courtReservations();
  if (id === "autumn") return mosaReservations();
  if (id === "sakura") return chillReservations();
  if (id === "water") return spaReservations();
  if (id === "clockwork") return cottonReservations();
  if (id === "summer") return capybaraReservations();
  const fixed = id === "moon" ? [
    { x: -6, z: -4, w: 1.8, d: 1.8 },
    { x: -2, z: 5, w: 2.5, d: 2.5 }
  ] : [];
  if (id === "aquapark")
    fixed.push(
      { x: -3, z: -8, w: 11, d: 10 },
      { x: 8, z: 6, w: 10, d: 8 },
      { x: 9, z: -7, w: 10, d: 9 },
      { x: -10, z: -8, w: 9, d: 8 }
    );
  if (RENEWED_ISLANDS[id]) {
    const upper = RENEWED_ISLANDS[id].upper;
    fixed.push({
      x: upper[0],
      z: upper[1],
      w: upper[2] * 2 + 0.7,
      d: upper[3] * 2 + 0.7,
      rx: upper[2] + 0.12,
      rz: upper[3] + 0.12
    });
    for (const ride of ISLAND_RIDES.filter((r) => r.biome === id)) {
      const item2 = byItem(ride.type);
      fixed.push({
        x: ride.x,
        z: ride.z,
        w: item2.footprint[0],
        d: item2.footprint[1]
      });
    }
  }
  const river = BIOME_STYLES[id]?.river;
  if (river)
    fixed.push({
      x: river[0],
      z: river[1],
      w: river[2] * 2,
      d: river[3] * 2,
      rx: river[2] + 0.12,
      rz: river[3] + 0.12
    });
  const water = BIOME_STYLES[id]?.water;
  if (water)
    fixed.push({
      x: water[0],
      z: water[1],
      w: water[2] * 2 + 0.4,
      d: water[3] * 2 + 0.4,
      rx: water[2] + 0.12,
      rz: water[3] + 0.12
    });
  return fixed;
}
