  if (previous && now < Math.max(previous.startedAt, previous.cancelledAt || 0)) throw Error("\u041D\u0435\u043A\u043E\u0440\u0435\u043A\u0442\u043D\u0438\u0439 \u0447\u0430\u0441 \u0432\u0456\u0437\u0438\u0442\u0443.");
  const next = structuredClone(game2);
  next.zoo = normalizeZoo(game2.zoo);
