  const label = document2.createElement("strong");
  label.textContent = "V19 \xB7 \u0442\u0435\u0441\u0442 \u0444\u0456\u0437\u0438\u043A\u0438 (\u0442\u0438\u043C\u0447\u0430\u0441\u043E\u0432\u0438\u0439 \u0441\u0442\u0435\u043D\u0434)";
