      $("chichi-camera-label").textContent = chichi ? "\u041F\u043E\u0432\u0435\u0440\u043D\u0443\u0442\u0438 \u0437\u0432\u0438\u0447\u0430\u0439\u043D\u0438\u0439 \u043E\u0433\u043B\u044F\u0434 \u0441\u0432\u0456\u0442\u0443" : "\u041A\u0430\u043C\u0435\u0440\u0430 \u0427\u0438\u0447\u0456 \xB7 \u0431\u043B\u0438\u0436\u0447\u0435 \u0434\u043E \u043C\u043E\u0440\u0434\u043E\u0447\u043A\u0438";
      $("camera-follow-exit").hidden = !enabled;
