  if (id === "foodcourt")
    $("island-summary").textContent = owned ? "\u041A\u043E\u0444\u0435\u0439\u043D\u044F \u0438 \u043A\u0438\u043D\u043E\u0442\u0435\u0430\u0442\u0440 \u0443\u0436\u0435 \u043E\u0442\u043A\u0440\u044B\u0442\u044B. \u041D\u0430\u0436\u043C\u0438\u0442\u0435 \u043D\u0430 \u0441\u0432\u043E\u0431\u043E\u0434\u043D\u0443\u044E \u043F\u043B\u043E\u0449\u0430\u0434\u043A\u0443, \u0447\u0442\u043E\u0431\u044B \u043F\u043E\u0441\u0442\u0440\u043E\u0438\u0442\u044C \u0431\u0443\u0440\u0433\u0435\u0440\u043D\u0443\u044E, \u0431\u0430\u0431\u043B-\u0442\u0438 \u0438\u043B\u0438 \u043F\u0435\u043A\u0430\u0440\u043D\u044E. \u0412 \u0440\u0430\u0431\u043E\u0442\u0430\u044E\u0449\u0435\u043C \u0437\u0430\u0432\u0435\u0434\u0435\u043D\u0438\u0438 \u043C\u043E\u0436\u043D\u043E \u0437\u0430\u0433\u043B\u044F\u043D\u0443\u0442\u044C \u0432\u043D\u0443\u0442\u0440\u044C \u0438 \u043F\u043E\u0437\u0432\u0430\u0442\u044C \u0427\u0438\u0447\u0438." : "\u0411\u043E\u043B\u044C\u0448\u043E\u0439 \u043A\u043E\u0442\u044F\u0447\u0438\u0439 \u0444\u0443\u0434-\u043A\u043E\u0440\u0442: \u043F\u044F\u0442\u044C \u0437\u0430\u0432\u0435\u0434\u0435\u043D\u0438\u0439, \u0442\u0435\u0440\u0440\u0430\u0441\u044B, \u043A\u0438\u043D\u043E \u043F\u043E\u0434 \u043E\u0442\u043A\u0440\u044B\u0442\u044B\u043C \u043D\u0435\u0431\u043E\u043C. \u041E\u0442\u043A\u0440\u043E\u0435\u0442\u0441\u044F \u0441 6 \u0443\u0440\u043E\u0432\u043D\u044F.";
  if (id === ZOO_ID) $("island-summary").textContent = "\u0428\u0456\u0441\u0442\u044C \u0432\u0435\u043B\u0438\u043A\u0438\u0445 \u043C\u0456\u043D\u0456\u0431\u0456\u043E\u043C\u0456\u0432, \u0446\u0435\u043D\u0442\u0440\u0430\u043B\u044C\u043D\u0430 \u043F\u043B\u043E\u0449\u0430 \u0439 \u043F\u0440\u043E\u0441\u0442\u043E\u0440\u0456 \u0434\u043E\u0440\u0456\u0436\u043A\u0438. \u0421\u043B\u043E\u043D\u043E\u0432\u0430 \u0434\u043E\u043B\u0438\u043D\u0430 \u0432\u0456\u0434\u043A\u0440\u0438\u0442\u0430 \u0432\u0456\u0434\u0440\u0430\u0437\u0443; \u0440\u0435\u0448\u0442\u0430 \u0432\u043E\u043B\u044C\u0454\u0440\u0456\u0432 \u0432\u0456\u0434\u043A\u0440\u0438\u0432\u0430\u044E\u0442\u044C\u0441\u044F \u043F\u043E\u0441\u043B\u0456\u0434\u043E\u0432\u043D\u043E \u0437\u0430 \u043C\u043E\u043D\u0435\u0442\u0438.";
